package com.splitmate.api; import com.splitmate.api.ApiDtos.*; import com.splitmate.domain.User; import com.splitmate.security.JwtService; import com.splitmate.service.SplitMateService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final SplitMateService service;private final JwtService jwt;public AuthController(SplitMateService s,JwtService j){service=s;jwt=j;} @PostMapping("/register") public AuthResponse register(@Valid @RequestBody Register x){return response(service.register(x));} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody Login x){return response(service.authenticate(x));}private AuthResponse response(User u){return new AuthResponse(jwt.create(u.email),u.id,u.name,u.email);} }
